# mpInstaller.py
# mpAnim  v1.0
# mpRig   v1.0
# Built   : 2026-06-05 21:44
#
# Drag this file into a Maya viewport to install the mpAnim and mpRig shelves.
# The studiolibrary_src/ folder must sit next to this file.
# Running it again will refresh all scripts and buttons.

import base64
import os

_SHELVES = {'mpAnim': [{'label': 'Playblast', 'tooltip': 'Open the Playblast Manager — creates versioned JPEG sequences with burn-ins', 'icon': 'playblast.png', 'script': 'pbTool.py', 'command': 'import importlib\nimport pbTool\nimportlib.reload(pbTool)\npbTool.show_pbTool()'}, {'label': 'CamPreset', 'tooltip': 'Open the Camera Preset Manager — save and apply named camera/render presets', 'icon': 'camera.png', 'script': 'ps_cam_preset_simple.py', 'command': 'import importlib\nimport ps_cam_preset_simple as ps\nimportlib.reload(ps)\nps.show()'}, {'label': 'ClothChain', 'tooltip': 'Open the Cloth Chain Sim tool — build and control nCloth chain rigs', 'icon': 'iconClothChain.png', 'script': 'tlmClothChain.py', 'command': 'import importlib\nimport tlmClothChain\nimportlib.reload(tlmClothChain)\nimport maya.cmds as cmds\nrun = tlmClothChain.SimClothRig()\ncmds.evalDeferred(run.UI)'}, {'label': 'StudioLib', 'tooltip': 'Open Studio Library — animation pose and clip manager', 'icon': 'iconStudioLib.png', 'command': 'import importlib\nimport studiolibrary\nimportlib.reload(studiolibrary)\nstudiolibrary.main()'}, {'label': 'JiffyPomo', 'tooltip': 'Open JiffyPomo — Pomodoro timer and task tracker for Maya artists', 'icon': 'iconJiffy.png', 'script': 'Jiffypomo.py', 'command': 'import importlib\nimport Jiffypomo\nimportlib.reload(Jiffypomo)\nJiffypomo.run_jiffypomo()'}, {'label': 'shortCuts', 'tooltip': 'Open shortCuts — manage and switch hotkey presets per workflow', 'icon': 'iconShortCuts.png', 'script': 'shortCuts.py', 'command': 'import importlib\nimport shortCuts\nimportlib.reload(shortCuts)\nshortCuts.show()'}], 'mpRig': [{'label': 'ps_spine', 'tooltip': 'Open ps_spine — build a ribbon spine rig from a drawn curve', 'icon': 'iconSpine.png', 'command': 'import importlib\nimport ps_spine\nimportlib.reload(ps_spine)\nps_spine.show()'}]}
_BUNDLED = {'mpAnimConfig.py': '', 'shortCuts.py': '', 'pbTool.py': '', 'ps_cam_preset_simple.py': '', 'tlmClothChain.py': '', 'Jiffypomo.py': '', 'multiTool.py': '', 'mtSnap.py': '', 'mtConstraints.py': '', 'mtAimRig.py': '', 'mtCycleKeys.py': '', 'mtGravity.py': '', 'mtBallistics.py': '', 'mtRefPlane.py': '', 'mtWSBake.py': '', 'mtOSBake.py': '', 'mtBakeDown.py': '', 'mtTips.py': '', 'mtPanic.py': '', 'ps_spine.py': ''}
_ICONS   = {'iconClothChain.png': '', 'iconStudioLib.png': '', 'iconJiffy.png': '', 'iconShortCuts.png': '', 'iconSpine.png': ''}

_USERSETUP_MARKER = "# multiTool auto-load (mpAnim installer)"
_USERSETUP_LINE   = "import maya.utils; maya.utils.executeDeferred('import multiTool; multiTool.show()')"


def _install():
    import shutil
    import maya.cmds as cmds
    import maya.mel as mel

    # Deploy all scripts
    scripts_dir = os.path.join(cmds.internalVar(userAppDir=True), "scripts")
    os.makedirs(scripts_dir, exist_ok=True)
    for filename, encoded in _BUNDLED.items():
        dest = os.path.join(scripts_dir, filename)
        with open(dest, "w", encoding="utf-8") as fh:
            fh.write(base64.b64decode(encoded.encode("ascii")).decode("utf-8"))

    # Deploy custom icons
    icons_dir = cmds.internalVar(userBitmapsDir=True)
    os.makedirs(icons_dir, exist_ok=True)
    for filename, encoded in _ICONS.items():
        dest = os.path.join(icons_dir, filename)
        with open(dest, "wb") as fh:
            fh.write(base64.b64decode(encoded.encode("ascii")))

    # Deploy Studio Library
    installer_dir = os.path.dirname(os.path.abspath(__file__))
    studiolib_src = os.path.join(installer_dir, "studiolibrary_src")
    if os.path.exists(studiolib_src):
        for pkg_name in os.listdir(studiolib_src):
            src = os.path.join(studiolib_src, pkg_name)
            if os.path.isdir(src):
                dst = os.path.join(scripts_dir, pkg_name)
                if os.path.exists(dst):
                    shutil.rmtree(dst)
                shutil.copytree(src, dst)
        print("[mpInstaller] deployed Studio Library")
    else:
        print("[mpInstaller] WARNING: studiolibrary_src not found")

    # Patch userSetup.py
    usersetup = os.path.join(scripts_dir, "userSetup.py")
    existing = ""
    if os.path.exists(usersetup):
        with open(usersetup, "r", encoding="utf-8") as fh:
            existing = fh.read()
    _OLD_MARKERS = [
        "# animMultiTool auto-load (mpAnim installer)",
        "import animMultiTool; animMultiTool.show()",
        "import maya.utils; maya.utils.executeDeferred('import animMultiTool; animMultiTool.show()')",
    ]
    for old in _OLD_MARKERS:
        if old in existing:
            existing = existing.replace(old, "")
    existing = "\n".join(line for line in existing.splitlines() if line.strip())
    if _USERSETUP_MARKER not in existing:
        with open(usersetup, "a", encoding="utf-8") as fh:
            fh.write("\n" + _USERSETUP_MARKER + "\n" + _USERSETUP_LINE + "\n")
        print("[mpInstaller] patched userSetup.py")
    else:
        print("[mpInstaller] userSetup.py already patched")

    # Build / refresh shelves
    shelf_top = mel.eval("$tmpVar=$gShelfTopLevel")
    existing_tabs = cmds.shelfTabLayout(shelf_top, query=True, childArray=True) or []

    for shelf_name, buttons in _SHELVES.items():
        if shelf_name not in existing_tabs:
            mel.eval(f'addNewShelfTab "{shelf_name}"')
            print(f"[mpInstaller] created shelf tab: {shelf_name}")

        shelf = f"{shelf_top}|{shelf_name}"
        for old_btn in cmds.shelfLayout(shelf, query=True, childArray=True) or []:
            cmds.deleteUI(old_btn)

        for btn in buttons:
            try:
                cmds.shelfButton(
                    parent=shelf,
                    label=btn["label"],
                    annotation=btn["tooltip"],
                    image1=btn.get("icon", "commandButton.png"),
                    command=btn["command"],
                    sourceType="python",
                )
                print(f"[mpInstaller] added button: {shelf_name} / {btn['label']}")
            except Exception as e:
                print(f"[mpInstaller] ERROR adding {btn['label']}: {e}")

    mel.eval("saveAllShelves $gShelfTopLevel")
    print("[mpInstaller] done")

    cmds.evalDeferred("import multiTool; multiTool.show()")
    cmds.evalDeferred("import mpAnimConfig; mpAnimConfig.get_save_path()")

    cmds.inViewMessage(
        amg="<b>mpAnim + mpRig</b> installed successfully.",
        pos="midCenter",
        fade=True,
    )


def onMayaDroppedPythonFile(*args):
    import sys
    import importlib
    mod = sys.modules.get(__name__)
    if mod is not None:
        importlib.reload(mod)
        sys.modules[__name__]._install()
    else:
        _install()
